const takeApprovedEnrollment = `-- name: TakeApprovedEnrollment :one
DELETE FROM device_enrollments
WHERE device_code_hash = ? AND device_id IS NOT NULL
RETURNING device_id
`

// Takes an approved enrollment once: deletes it and returns the device id. No row: unknown,
// not approved yet or already taken.
func (q *Queries) TakeApprovedEnrollment(ctx context.Context, deviceCodeHash []byte) (sql.NullInt64, error) {
	row := q.db.QueryRowContext(ctx, takeApprovedEnrollment, deviceCodeHash)
	var device_id sql.NullInt64
	err := row.Scan(&device_id)
	return device_id, err
}

