const touchEnrollmentPoll = `-- name: TouchEnrollmentPoll :execrows
UPDATE device_enrollments SET polled_at = ?1
WHERE device_code_hash = ?2 AND polled_at <= ?3
`

type TouchEnrollmentPollParams struct {
	Now            int64
	DeviceCodeHash []byte
	MinPolledAt    int64
}

// Records a poll when the last one was at or before min_polled_at. 0 rows: unknown, or the
// client polls too fast (answer slow_down).
func (q *Queries) TouchEnrollmentPoll(ctx context.Context, arg TouchEnrollmentPollParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, touchEnrollmentPoll, arg.Now, arg.DeviceCodeHash, arg.MinPolledAt)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

